   283	VC5Decompressor::VC5Decompressor(ByteStream bs, const RawImage& img)
   284	    : mRaw(img), mBs(std::move(bs)) {
   285	  if (!mRaw->dim.hasPositiveArea())
   286	    ThrowRDE("Bad image dimensions.");
   287	
   288	  if (mRaw->dim.x % mVC5.patternWidth != 0)
   289	    ThrowRDE("Width %u is not a multiple of %u", mRaw->dim.x,
   290	             mVC5.patternWidth);
   291	
   292	  if (mRaw->dim.y % mVC5.patternHeight != 0)
   293	    ThrowRDE("Height %u is not a multiple of %u", mRaw->dim.y,
   294	             mVC5.patternHeight);
   295	
   296	  if (mRaw->dim.x > std::numeric_limits<decltype(Channel::width)>::max())
   297	    ThrowRDE("Width %u is too large", mRaw->dim.x);
   298	
   299	  if (mRaw->dim.y > std::numeric_limits<decltype(Channel::height)>::max())
   300	    ThrowRDE("Height %u is too large", mRaw->dim.y);
   301	
   302	  // Initialize wavelet sizes.
   303	  for (Channel& channel : channels) {
   304	    channel.width = mRaw->dim.x / mVC5.patternWidth;
   305	    channel.height = mRaw->dim.y / mVC5.patternHeight;
   306	
   307	    uint16_t waveletWidth = channel.width;
   308	    uint16_t waveletHeight = channel.height;
   309	    for (Wavelet& wavelet : channel.wavelets) {
   310	      // Pad dimensions as necessary and divide them by two for the next wavelet
   311	      for (auto* dimension : {&waveletWidth, &waveletHeight})
   312	        *dimension = roundUpDivision(*dimension, 2);
   313	      wavelet.width = waveletWidth;
   314	      wavelet.height = waveletHeight;
   315	    }
   316	  }
   317	
   318	  if (img->whitePoint <= 0 || img->whitePoint > int(((1U << 16U) - 1U)))
   319	    ThrowRDE("Bad white level %i", img->whitePoint);
   320	
   321	  outputBits = 0;
   322	  for (int wp = img->whitePoint; wp != 0; wp >>= 1)
   323	    ++outputBits;
   324	  assert(outputBits <= 16);
   325	
   326	  parseVC5();
   327	}
   328	
   329	void VC5Decompressor::initVC5LogTable() {
   330	  mVC5LogTable = decltype(mVC5LogTable)(
   331	      [outputBits = outputBits](unsigned i, unsigned tableSize) {
   332	        // The vanilla "inverse log" curve for decoding.
   333	        auto normalizedCurve = [](auto normalizedI) {
   334	          return (std::pow(113.0, normalizedI) - 1) / 112.0;
   335	        };
   336	
   337	        auto normalizeI = [tableSize](auto x) { return x / (tableSize - 1.0); };
   338	        auto denormalizeY = [maxVal = std::numeric_limits<ushort16>::max()](
   339	                                auto y) { return maxVal * y; };
   340	        // Adjust for output whitelevel bitdepth.
   341	        auto rescaleY = [outputBits](auto y) {
   342	          auto scale = 16 - outputBits;
   343	          return y >> scale;
   344	        };
   345	
   346	        const auto naiveY = denormalizeY(normalizedCurve(normalizeI(i)));
   347	        const auto intY = static_cast<unsigned int>(naiveY);
   348	        const auto rescaledY = rescaleY(intY);
   349	        return rescaledY;
   350	      });
   351	}
   352	
   353	const SimpleLUT<int16_t, 16> VC5Decompressor::mVC5DecompandingTable = []() {
   354	  auto dequantize = [](int16_t val) -> int16_t {
   355	    double c = val;
   356	    // Invert companding curve
   357	    c += (c * c * c * 768) / (255. * 255. * 255.);
   358	    if (c > std::numeric_limits<int16_t>::max())
   359	      return std::numeric_limits<int16_t>::max();
   360	    if (c < std::numeric_limits<int16_t>::min())
   361	      return std::numeric_limits<int16_t>::min();
   362	    return c;
   363	  };
   364	  return decltype(mVC5DecompandingTable)(
   365	      [dequantize](unsigned i, unsigned tableSize) {
   366	        return dequantize(int16_t(uint16_t(i)));
   367	      });
   368	}();
   369	
   370	void VC5Decompressor::parseVC5() {
   371	  mBs.setByteOrder(Endianness::big);
   372	
   373	  assert(mRaw->dim.x > 0);
   374	  assert(mRaw->dim.y > 0);
   375	
   376	  // All VC-5 data must start with "VC-%" (0x56432d35)
   377	  if (mBs.getU32() != 0x56432d35)
   378	    ThrowRDE("not a valid VC-5 datablock");
   379	
   380	  bool done = false;
   381	  while (!done) {
   382	    auto tag = static_cast<VC5Tag>(mBs.getU16());
   383	    ushort16 val = mBs.getU16();
   384	
   385	    bool optional = matches(tag, VC5Tag::Optional);
   386	    if (optional)
   387	      tag = -tag;
   388	
   389	    switch (tag) {
   390	    case VC5Tag::ChannelCount:
   391	      if (val != numChannels)
   392	        ThrowRDE("Bad channel count %u, expected %u", val, numChannels);
   393	      break;
   394	    case VC5Tag::ImageWidth:
   395	      if (val != mRaw->dim.x)
   396	        ThrowRDE("Image width mismatch: %u vs %u", val, mRaw->dim.x);
   397	      break;
   398	    case VC5Tag::ImageHeight:
   399	      if (val != mRaw->dim.y)
   400	        ThrowRDE("Image height mismatch: %u vs %u", val, mRaw->dim.y);
   401	      break;
   402	    case VC5Tag::LowpassPrecision:
   403	      if (val < PRECISION_MIN || val > PRECISION_MAX)
   404	        ThrowRDE("Invalid precision %i", val);
   405	      mVC5.lowpassPrecision = val;
   406	      break;
   407	    case VC5Tag::ChannelNumber:
   408	      if (val >= numChannels)
   409	        ThrowRDE("Bad channel number (%u)", val);
   410	      mVC5.iChannel = val;
   411	      break;
   412	    case VC5Tag::ImageFormat:
   413	      if (val != mVC5.imgFormat)
   414	        ThrowRDE("Image format %i is not 4(RAW)", val);
   415	      break;
   416	    case VC5Tag::SubbandCount:
   417	      if (val != numSubbands)
   418	        ThrowRDE("Unexpected subband count %u, expected %u", val, numSubbands);
   419	      break;
   420	    case VC5Tag::MaxBitsPerComponent:
   421	      if (val != VC5_LOG_TABLE_BITWIDTH) {
   422	        ThrowRDE("Bad bits per componend %u, not %u", val,
   423	                 VC5_LOG_TABLE_BITWIDTH);
   424	      }
   425	      break;
   426	    case VC5Tag::PatternWidth:
   427	      if (val != mVC5.patternWidth)
   428	        ThrowRDE("Bad pattern width %u, not %u", val, mVC5.patternWidth);
   429	      break;
   430	    case VC5Tag::PatternHeight:
   431	      if (val != mVC5.patternHeight)
   432	        ThrowRDE("Bad pattern height %u, not %u", val, mVC5.patternHeight);
   433	      break;
   434	    case VC5Tag::SubbandNumber:
   435	      if (val >= numSubbands)
   436	        ThrowRDE("Bad subband number %u", val);
   437	      mVC5.iSubband = val;
   438	      break;
   439	    case VC5Tag::Quantization:
   440	      mVC5.quantization = static_cast<short16>(val);
   441	      break;
   442	    case VC5Tag::ComponentsPerSample:
   443	      if (val != mVC5.cps)
   444	        ThrowRDE("Bad compnent per sample count %u, not %u", val, mVC5.cps);
   445	      break;
   446	    case VC5Tag::PrescaleShift:
   447	      // FIXME: something is wrong. We get this before VC5Tag::ChannelNumber.
   448	      // Defaulting to 'mVC5.iChannel=0' seems to work *for existing samples*.
   449	      for (int iWavelet = 0; iWavelet < numWaveletLevels; ++iWavelet) {
   450	        auto& channel = channels[mVC5.iChannel];
   451	        auto& wavelet = channel.wavelets[iWavelet];
   452	        wavelet.prescale = (val >> (14 - 2 * iWavelet)) & 0x03;
   453	      }
   454	      break;
   455	    default: { // A chunk.
   456	      unsigned in<response clipped><NOTE>Due to the max output limit, only part of this file has been shown to you. You should retry this tool after you have searched inside the file with `grep -n` in order to find the line numbers of what you are looking for.</NOTE>

default: { // A chunk.
      unsigned int chunkSize = 0;
      if (matches(tag, VC5Tag::LARGE_CHUNK)) {
        chunkSize = static_cast<unsigned int>(
            ((static_cast<std::underlying_type<VC5Tag>::type>(tag) & 0xff)
             << 16) |
            (val & 0xffff));
      } else if (matches(tag, VC5Tag::SMALL_CHUNK)) {
        chunkSize = (val & 0xffff);
      }

      if (is(tag, VC5Tag::LargeCodeblock)) {
        parseLargeCodeblock(mBs.getStream(chunkSize, 4));
        break;
      }

      // And finally, we got here if we didn't handle this tag/maybe-chunk.

      // Magic, all the other 'large' chunks are actually optional,
      // and don't specify any chunk bytes-to-be-skipped.
      if (matches(tag, VC5Tag::LARGE_CHUNK)) {
        optional = true;
        chunkSize = 0;
      }

      if (!optional) {
        ThrowRDE("Unknown (unhandled) non-optional Tag 0x%04hx",
                 static_cast<std::underlying_type<VC5Tag>::type>(tag));
      }

      if (chunkSize)
        mBs.skipBytes(chunkSize, 4);

      break;
    }
    }

    done = true;
    for (int iChannel = 0; iChannel < numChannels && done; ++iChannel) {
      Wavelet& wavelet = channels[iChannel].wavelets[0];
      if (!wavelet.allBandsValid())
        done = false;
    }
  }
}

void VC5Decompressor::Wavelet::LowPassBand::decode(const Wavelet& wavelet) {
  data = Array2DRef<int16_t>::create(wavelet.width, wavelet.height);
  const Array2DRef<int16_t> dst(data.data(), wavelet.width, wavelet.height);

  BitPumpMSB bits(bs);
  for (auto row = 0U; row < dst.height; ++row) {
    for (auto col = 0U; col < dst.width; ++col)
      dst(col, row) = static_cast<int16_t>(bits.getBits(lowpassPrecision));
  }
}

void VC5Decompressor::Wavelet::HighPassBand::decode(const Wavelet& wavelet) {
  auto dequantize = [quant = quant](int16_t val) -> int16_t {
    return mVC5DecompandingTable[uint16_t(val)] * quant;
  };

  data = Array2DRef<int16_t>::create(wavelet.width, wavelet.height);
  const Array2DRef<int16_t> dst(data.data(), wavelet.width, wavelet.height);

  BitPumpMSB bits(bs);
  // decode highpass band
  int pixelValue = 0;
  unsigned int count = 0;
  int nPixels = wavelet.width * wavelet.height;
  for (int iPixel = 0; iPixel < nPixels;) {
    getRLV(&bits, &pixelValue, &count);
    for (; count > 0; --count) {
      if (iPixel > nPixels)
        ThrowRDE("Buffer overflow");
      data[iPixel] = dequantize(pixelValue);
      ++iPixel;
    }
  }
  if (bits.getPosition() < bits.getSize()) {
    getRLV(&bits, &pixelValue, &count);
    if (pixelValue != MARKER_BAND_END || count != 0)
      ThrowRDE("EndOfBand marker not found");
  }
}

void VC5Decompressor::parseLargeCodeblock(const ByteStream& bs) {
  static const auto subband_wavelet_index = []() {
    std::array<int, numSubbands> wavelets;
    int wavelet = 0;
    for (auto i = wavelets.size() - 1; i > 0;) {
      for (auto t = 0; t < numWaveletLevels; t++) {
        wavelets[i] = wavelet;
        i--;
      }
      if (i > 0)
        wavelet++;
    }
    wavelets.front() = wavelet;
    return wavelets;
  }();
  static const auto subband_band_index = []() {
    std::array<int, numSubbands> bands;
    bands.front() = 0;
    for (auto i = 1U; i < bands.size();) {
      for (int t = 1; t <= numWaveletLevels;) {
        bands[i] = t;
        t++;
        i++;
      }
    }
    return bands;
  }();

  const int idx = subband_wavelet_index[mVC5.iSubband];
  const int band = subband_band_index[mVC5.iSubband];

  auto& wavelets = channels[mVC5.iChannel].wavelets;

  Wavelet& wavelet = wavelets[idx];
  if (wavelet.isBandValid(band)) {
    ThrowRDE("Band %u for wavelet %u on channel %u was already seen", band, idx,
             mVC5.iChannel);
  }

  std::unique_ptr<Wavelet::AbstractBand>& dstBand = wavelet.bands[band];
  if (mVC5.iSubband == 0) {
    assert(band == 0);
    // low-pass band, only one, for the smallest wavelet, per channel per image
    dstBand = std::make_unique<Wavelet::LowPassBand>(bs, mVC5.lowpassPrecision);
  } else {
    dstBand = std::make_unique<Wavelet::HighPassBand>(bs, mVC5.quantization);
  }
  wavelet.setBandValid(band);

  // If this wavelet is fully specified, mark the low-pass band of the
  // next lower wavelet as specified.
  if (idx > 0 && wavelet.allBandsValid()) {
    Wavelet& nextWavelet = wavelets[idx - 1];
    assert(!nextWavelet.isBandValid(0));
    nextWavelet.bands[0] = std::make_unique<Wavelet::ReconstructableBand>();
    nextWavelet.setBandValid(0);
  }
}

void VC5Decompressor::decode(unsigned int offsetX, unsigned int offsetY,
